/**
 * 错误码：JSON-RPC error.code 使用 -32000 起的服务端自定义区间，
 * error.data.errorCode 携带机器可读字符串码，View 据此决定 UI 反馈。
 */
import type { JsonRpcError } from './envelope';

export const RUNTIME_ERROR_CODES = [
  'AUTH_REQUIRED',
  'ENTITLEMENT_DENIED',
  'QUOTA_EXCEEDED',
  'STUDIO_NOT_READY',
  'STALE_REVISION',
  'INVALID_ARGUMENT',
  'METHOD_NOT_FOUND',
  'METHOD_NOT_ALLOWED',
  'DEPENDENCY_MISSING',
  'VALIDATION_FAILED',
  'CANCELLED',
  'NETWORK_ERROR',
  'RESULT_UNKNOWN',
  'HISTORY_TOO_LARGE',
  'SKILL_STATE_UPDATING',
  'SKILL_RECOVERY_REQUIRED',
  'SKILL_NOT_EFFECTIVE',
  'INSTALLATION_QUOTA_EXCEEDED',
  'INSTALLATION_DISABLED',
  'INSTALLATION_POLICY_UNAVAILABLE',
  'INSTALLATION_AUTHORIZATION_INVALID',
  'INSTALLATION_BUDGET_EXCEEDED',
  'INSTALLATION_EXPIRED',
  'INSTALLATION_BILLING_UNAVAILABLE',
  'INSTALLATION_REVIEW_FAILED',
  'INSTALLATION_REVIEW_TIMEOUT',
  'INSTALLATION_REVIEW_INVALID',
  'WORKSPACE_BUSY',
  'PROJECT_NOT_FOUND',
  'DRAFT_NOT_FOUND',
  'DRAFT_STALE',
  'DRAFT_QUOTA_EXCEEDED',
  'CODEX_NOT_RUNNING',
  'APP_SERVER_OVERLOADED',
  'REQUEST_TIMEOUT',
  'APP_SERVER_REQUEST_FAILED',
  'INTERNAL',
] as const;
export type RuntimeErrorCode = (typeof RUNTIME_ERROR_CODES)[number];

const NUMERIC: Record<RuntimeErrorCode, number> = {
  METHOD_NOT_FOUND: -32601,
  INVALID_ARGUMENT: -32602,
  INTERNAL: -32603,
  METHOD_NOT_ALLOWED: -32000,
  AUTH_REQUIRED: -32001,
  ENTITLEMENT_DENIED: -32002,
  QUOTA_EXCEEDED: -32003,
  STUDIO_NOT_READY: -32004,
  STALE_REVISION: -32005,
  DEPENDENCY_MISSING: -32006,
  VALIDATION_FAILED: -32007,
  CANCELLED: -32008,
  NETWORK_ERROR: -32009,
  RESULT_UNKNOWN: -32010,
  CODEX_NOT_RUNNING: -32011,
  HISTORY_TOO_LARGE: -32012,
  SKILL_STATE_UPDATING: -32013,
  SKILL_RECOVERY_REQUIRED: -32014,
  SKILL_NOT_EFFECTIVE: -32015,
  INSTALLATION_QUOTA_EXCEEDED: -32016,
  INSTALLATION_DISABLED: -32017,
  INSTALLATION_POLICY_UNAVAILABLE: -32018,
  INSTALLATION_AUTHORIZATION_INVALID: -32019,
  INSTALLATION_BUDGET_EXCEEDED: -32020,
  INSTALLATION_EXPIRED: -32021,
  WORKSPACE_BUSY: -32022,
  PROJECT_NOT_FOUND: -32023,
  DRAFT_NOT_FOUND: -32024,
  DRAFT_STALE: -32025,
  DRAFT_QUOTA_EXCEEDED: -32026,
  INSTALLATION_BILLING_UNAVAILABLE: -32027,
  INSTALLATION_REVIEW_FAILED: -32028,
  INSTALLATION_REVIEW_TIMEOUT: -32029,
  INSTALLATION_REVIEW_INVALID: -32030,
  APP_SERVER_OVERLOADED: -32031,
  REQUEST_TIMEOUT: -32032,
  APP_SERVER_REQUEST_FAILED: -32033,
};

export function makeError(
  errorCode: RuntimeErrorCode,
  message: string,
  extra?: Record<string, unknown>,
): JsonRpcError {
  return {
    code: NUMERIC[errorCode],
    message,
    data: { errorCode, ...extra },
  };
}

export function errorCodeOf(error: JsonRpcError | undefined | null): RuntimeErrorCode | undefined {
  const data = error?.data;
  if (data && typeof data === 'object' && 'errorCode' in data) {
    const code = (data as { errorCode?: unknown }).errorCode;
    if (typeof code === 'string' && (RUNTIME_ERROR_CODES as readonly string[]).includes(code)) {
      return code as RuntimeErrorCode;
    }
  }
  return undefined;
}

/** 便于在 Node/Electron 侧把 JSON-RPC error 转成异常抛出 */
export class RuntimeRpcError extends Error {
  readonly rpc: JsonRpcError;
  readonly errorCode: RuntimeErrorCode | undefined;
  constructor(error: JsonRpcError) {
    super(error.message);
    this.name = 'RuntimeRpcError';
    this.rpc = error;
    this.errorCode = errorCodeOf(error);
  }
}
